"use client";

import { useState, useEffect } from "react";
import { Calendar, CheckCircle } from "lucide-react";
import SessionCard from "./SessionCard";
import SessionReservationModal from "./SessionReservationModal";
import Button from "@/components/UI/Button";

interface Session {
  id: number;
  title: string;
  startDate: string;
  endDate: string | null;
  mode: "PARTNER_CENTER" | "E_LEARNING";
  location: string | null;
  availableSpots: number | null;
  isFull: boolean;
}

interface SessionsSectionProps {
  formationId: number;
  formationTitle: string;
  categoryName?: string;
}

export default function SessionsSection({
  formationId,
  formationTitle,
  categoryName,
}: SessionsSectionProps) {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedSession, setSelectedSession] = useState<Session | null>(null);
  const [showSuccess, setShowSuccess] = useState(false);

  useEffect(() => {
    const fetchSessions = async () => {
      try {
        const response = await fetch(
          `/api/sessions/public?trainingId=${formationId}`
        );
        if (response.ok) {
          const data = await response.json();
          setSessions(data);
        }
      } catch (error) {
        console.error("Error fetching sessions:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchSessions();
  }, [formationId]);

  const handleReserve = (session: Session) => {
    setSelectedSession(session);
  };

  const handleCloseModal = () => {
    setSelectedSession(null);
  };

  const handleSuccess = () => {
    setSelectedSession(null);
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 5000);
  };

  if (loading) {
    return (
      <div className="bg-white rounded-4xl p-6 border border-gray-200">
        <div className="animate-pulse space-y-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gray-200 rounded-xl" />
            <div className="h-6 bg-gray-200 rounded w-40" />
          </div>
          <div className="h-20 bg-gray-100 rounded-3xl" />
          <div className="h-20 bg-gray-100 rounded-3xl" />
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="bg-white rounded-4xl p-6 border border-gray-200 shadow-sm">
        {/* Header */}
        <div className="flex items-center gap-3 mb-5">
          <div className="w-10 h-10 bg-primary/10 rounded-xl flex items-center justify-center">
            <Calendar className="w-5 h-5 text-primary" />
          </div>
          <h3 className="font-satoshi text-lg font-bold text-darkBlue">
            Sessions disponibles
          </h3>
        </div>

        {/* Success message */}
        {showSuccess && (
          <div className="mb-5 p-4 bg-green-50 border border-green-100 rounded-2xl flex items-start gap-3">
            <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center shrink-0">
              <CheckCircle className="w-4 h-4 text-green-600" />
            </div>
            <div>
              <p className="font-satoshi font-bold text-green-800 text-sm">
                Demande envoyée !
              </p>
              <p className="text-xs text-green-700 font-satoshi">
                Notre équipe vous contactera sous 24h pour finaliser votre inscription.
              </p>
            </div>
          </div>
        )}

        {sessions.length === 0 ? (
          /* Empty state */
          <div className="text-center py-8">
            <div className="w-16 h-16 bg-gray-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <Calendar className="w-8 h-8 text-grayBlue" />
            </div>
            <p className="font-satoshi font-bold text-darkBlue mb-1">
              Aucune session programmée
            </p>
            <p className="text-sm text-grayBlue font-satoshi mb-5">
              Contactez-nous pour planifier une date
            </p>
            <Button href="/devis-&-contact" variant="secondary">
              Demander une session
            </Button>
          </div>
        ) : (
          /* Sessions list */
          <div className="space-y-3">
            {sessions.map((session) => (
              <SessionCard
                key={session.id}
                session={session}
                onReserve={handleReserve}
              />
            ))}
          </div>
        )}
      </div>

      {/* Modal */}
      {selectedSession && (
        <SessionReservationModal
          session={selectedSession}
          formationId={formationId}
          formationTitle={formationTitle}
          categoryName={categoryName}
          onClose={handleCloseModal}
          onSuccess={handleSuccess}
        />
      )}
    </>
  );
}
