"use client";

import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { Calendar, MapPin, Monitor, Building, Users, ArrowRight } from "lucide-react";

interface Session {
  id: number;
  title: string;
  startDate: string;
  endDate: string | null;
  mode: "PARTNER_CENTER" | "E_LEARNING";
  location: string | null;
  availableSpots: number | null;
  isFull: boolean;
}

interface SessionCardProps {
  session: Session;
  onReserve: (session: Session) => void;
}

export default function SessionCard({ session, onReserve }: SessionCardProps) {
  const startDate = new Date(session.startDate);
  const endDate = session.endDate ? new Date(session.endDate) : null;

  const formatSessionDate = () => {
    const start = format(startDate, "d MMMM yyyy", { locale: fr });
    if (endDate) {
      const end = format(endDate, "d MMMM yyyy", { locale: fr });
      if (start === end) return start;
      return `${start} - ${end}`;
    }
    return start;
  };

  const ModeIcon = session.mode === "E_LEARNING" ? Monitor : Building;
  const modeLabel = session.mode === "E_LEARNING" ? "E-learning" : "Présentiel";

  return (
    <div
      className={`
        relative bg-gray-100 rounded-3xl p-5 border transition-all duration-300 group
        ${session.isFull
          ? "border-gray-200 opacity-60"
          : "border-gray-200 hover:border-primary/40 hover:shadow-lg cursor-pointer"
        }
      `}
      onClick={() => !session.isFull && onReserve(session)}
    >
      {/* Content */}
      <div className="flex items-center justify-between gap-4">
        {/* Left side - Date and info */}
        <div className="flex items-center gap-4">
          {/* Calendar icon box */}
          <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center border border-gray-200 shrink-0">
            <Calendar className="w-5 h-5 text-primary" />
          </div>

          {/* Info */}
          <div className="space-y-1">
            <p className="font-satoshi font-bold text-darkBlue">
              {formatSessionDate()}
            </p>
            <div className="flex items-center gap-3 text-sm text-grayBlue font-satoshi">
              <span className="flex items-center gap-1">
                <ModeIcon className="w-3.5 h-3.5" />
                {modeLabel}
              </span>
              {session.location && session.mode === "PARTNER_CENTER" && (
                <span className="flex items-center gap-1">
                  <MapPin className="w-3.5 h-3.5" />
                  {session.location}
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Right side - Places + Button */}
        <div className="flex items-center gap-3">
          {/* Places badge */}
          {session.availableSpots !== null && (
            <div className={`
              flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-satoshi font-medium
              ${session.isFull
                ? "bg-red-50 text-red-600"
                : "bg-primary/10 text-primary"
              }
            `}>
              <Users className="w-3.5 h-3.5" />
              {session.isFull ? (
                "Complet"
              ) : (
                <>{session.availableSpots} place{session.availableSpots > 1 ? "s" : ""}</>
              )}
            </div>
          )}

          {/* Arrow button */}
          {!session.isFull && (
            <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center border border-gray-200 group-hover:bg-primary group-hover:border-primary transition-all duration-300 shrink-0">
              <ArrowRight className="w-4 h-4 text-darkBlue group-hover:text-white transition-colors" />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
